import sys,numpy as np,mujoco
from scipy.spatial.transform import Rotation
sys.path.insert(0,'/opt/tools'); import casa_tool
s=casa_tool.Session(); m,d=s.model,s.data; sid=m.site('gripper0_right_grip_site').id
qadr=np.array([m.joint(f'robot0_joint{i}').qposadr[0] for i in range(1,8)]); dadr=np.array([m.joint(f'robot0_joint{i}').dofadr[0] for i in range(1,8)]); lim=np.array([m.joint(f'robot0_joint{i}').range for i in range(1,8)])
def ik(p,R=None):
 kd=mujoco.MjData(m); kd.qpos[:]=d.qpos; mujoco.mj_forward(m,kd); q=kd.qpos[qadr].copy()
 if R is None: R=kd.site_xmat[sid].reshape(3,3).copy()
 for _ in range(160):
  kd.qpos[qadr]=q; mujoco.mj_forward(m,kd); ep=p-kd.site_xpos[sid]; rr=Rotation.from_matrix(R@kd.site_xmat[sid].reshape(3,3).T).as_rotvec()
  jp=np.zeros((3,m.nv)); jr=np.zeros((3,m.nv)); mujoco.mj_jacSite(m,kd,jp,jr,sid); J=np.vstack((jp[:,dadr],.22*jr[:,dadr])); e=np.r_[ep,.22*rr]; dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-4,e); q=np.clip(q+np.clip(dq,-.07,.07),lim[:,0]+1e-4,lim[:,1]-1e-4)
 return q
def step(q=None, grip=-1, n=1):
 a=s.hold_targets(); a[8:12]=0; a[12]=-1
 if q is not None:a[:7]=q
 a[7]=grip
 for _ in range(n):s.step(a)
def move(p,n,grip,R):
 q=ik(np.array(p),R); step(q,grip,n); print('move',p,'eef',d.site_xpos[sid].copy(),'q',d.qpos[qadr].copy(),'door',d.qpos[m.joint('fridge_left_group_fridge_right_door_joint').qposadr[0]], flush=True); return q
a=s.initial_command(); a[8]=.85;a[11]=1;a[12]=1
for _ in range(18):s.step(a)
R=d.site_xmat[sid].reshape(3,3).copy()
print('init after reposition eef',d.site_xpos[sid].copy(),'gripper bodies')
for i in range(m.nbody):
 n=m.body(i).name
 if 'gripper0_right_' in n and ('finger' in n): print(n,d.xpos[i].copy())
# handle right
q=move([.59,-1.645,1.30],30,-1,R)
q=move([.586,-1.644,1.123],25,-1,R)
q=step(q,1,25)
print('closed handle',d.site_xpos[sid].copy(),'door',d.qpos[m.joint('fridge_left_group_fridge_right_door_joint').qposadr[0]],'contact handle',s.env.check_contact(s.env.robots[0],s.env.fixtures['fridge_left_group']))
q=move([.76,-1.644,1.123],45,1,R)
print('pulled door',d.qpos[m.joint('fridge_left_group_fridge_right_door_joint').qposadr[0]],'left',d.qpos[m.joint('fridge_left_group_fridge_left_door_joint').qposadr[0]])
print('eef',d.site_xpos[sid].copy(),'doorbody',d.xpos[m.body('fridge_left_group_fridge_right_door').id].copy())
s.close()
