def ik(p,R):
 kd=mujoco.MjData(m);kd.qpos[:]=d.qpos;mujoco.mj_forward(m,kd);q=kd.qpos[qa].copy()
 for _ in range(200):
  kd.qpos[qa]=q;mujoco.mj_forward(m,kd);ep=np.asarray(p)-kd.site_xpos[sid]; er=Rotation.from_matrix(R@kd.site_xmat[sid].reshape(3,3).T).as_rotvec()
  jp=np.zeros((3,m.nv));jr=np.zeros((3,m.nv));mujoco.mj_jacSite(m,kd,jp,jr,sid);J=np.vstack([jp[:,da],.22*jr[:,da]]);e=np.r_[ep,.22*er];dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-4,e);q=np.clip(q+np.clip(dq,-.07,.07),lim[:,0]+.001,lim[:,1]-.001)
