a=s.hold_targets();a[:7]=q;a[7]=1;a[8:12]=0;a[12]=-1
for _ in range(30):s.step(a)
print('close q door',d.qpos[m.joint('fridge_left_group_fridge_right_door_joint').qposadr[0]],'contacts',d.ncon)
for i in range(d.ncon):
 c=d.contact[i]; n1=m.geom(c.geom1).name;n2=m.geom(c.geom2).name
 if 'fridge_left_group_fridge_right_door_handle' in n1+n2 or ('gripper0_right' in n1+n2 and 'fridge_left_group_fridge_right' in n1+n2): print('contact',n1,n2)
q=execute([.80,-1.644,1.123],R,40,1)
print('doors',d.qpos[m.joint('fridge_left_group_fridge_right_door_joint').qposadr[0]],d.qpos[m.joint('fridge_left_group_fridge_left_door_joint').qposadr[0]])
